use vstd::prelude::*;

verus! {

/// Given a non‐empty input vector `t` of `char`s, construct and return
/// a new vector `out` by iterating from start to end and pushing each
/// character.  We prove that `out` has the same length as `t` and that
/// for every index in the constructed prefix, `out[i] == t[i]`.
fn solve(t: Vec<char>) -> Vec<char>
    requires
        // as per the problem statement, the input is non‐empty
        t.len() >= 1,
    ensures
        // the output has exactly the same length as the input
        result.len() == t.len(),
        // and for every index i < t.len(), result[i] == t[i]
        forall(|i: usize| i < t.len() ==> result[i] == t[i]),
{
    let n = t.len();
    let mut out: Vec<char> = Vec::new();
    let mut i: usize = 0;

    // We loop while there remain characters to process.
    // The loop invariant maintains:
    //  1. 0 ≤ i ≤ n
    //  2. out.len() == i
    //  3. for all j < i, out[j] == t[j]
    // The loop decreases on (n - i), so it terminates.
    while i < n
        invariant
            i <= n,
            out.len() == i,
            forall(|j: usize| j < i ==> out[j] == t[j]),
        decreases
            n - i,
    {
        // read the next character
        let c = t[i];
        // append it to the output
        out.push(c);
        // advance the index
        i = i + 1;
    }

    // At this point, i == n and out.len() == n, and the invariant
    // ensures out[j] == t[j] for all j < n, i.e. out == t.
    out
}

} // end verus! block

